"""Builds model-explained.html and model-technical.html from evaluation_v4.json so the pages always match the latest run."""
import json, re, html, os
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE)
R = json.load(open(os.path.join(ROOT, "results", "evaluation_v4.json")))
old = open(os.path.join(ROOT, "archive_old_prototype", "ligtas-explained.html")).read()
CSS = re.search(r"<style>(.*?)</style>", old, re.S).group(1) + """
table{border-collapse:collapse;width:100%;margin:14px 0;font-size:14px}th,td{border:1px solid var(--line);padding:6px 9px;text-align:left}th{background:var(--accent-soft)}
td.n{text-align:right;font-variant-numeric:tabular-nums}.small{font-size:14px;color:var(--muted)}
"""
f = lambda v, d=2: "-" if v is None else f"{v:.{d}f}"
sweep, curve, clean = R["expiry_sweep"], R["history_curve"], R["cleaning"]
def tbl(head, rows):
    return "<table><tr>" + "".join(f"<th>{h}</th>" for h in head) + "</tr>" + "".join("<tr>" + "".join(f"<td{' class=n' if i else ''}>{c}</td>" for i, c in enumerate(r)) + "</tr>" for r in rows) + "</table>"
sweep_rows = [[n, v["trips"], f(v["ap_model_2"]), f(v["ap_persist_2"]), f(v["ece_2"], 3), f(v["conf_coverage"]), f(v["false_alarms_per_trip_forecast"]), f(v["false_alarms_per_trip_persist"]), f(v["alerts_per_hour_forecast"], 1), v["scored_windows"]] for n, v in sweep.items() if v]
curve_rows = [[c["history"], c["trips"], f(c["ap_model_2"]), f(c["ap_persist_2"]), f(c["ece_2"], 3), f(c["conf_coverage"]), f(c["false_alarms_per_trip_forecast"])] for c in curve]
SW = tbl(["History kept", "Trips", "Forecast AP (Major+)", "Baseline AP", "Calibration error", "Empirical set coverage", "False alarms / trip, forecast", "False alarms / trip, baseline", "Alerts per hour, forecast", "Scored windows"], sweep_rows)
CV = tbl(["Earlier trips in history", "Trips", "Forecast AP (Major+)", "Baseline AP", "Calibration error", "Empirical set coverage", "False alarms / trip, forecast"], curve_rows)
NOTE = "<div class='callout'><b>Generated test data.</b> This replay verifies the software pipeline.</div>" if R.get("data_source") == "synthetic" else ""

def page(title, eyebrow, h1, lede, body):
    return f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><style>{CSS}</style></head><body>
<header><div class="wrap"><div class="eyebrow">{eyebrow}</div><h1>{h1}</h1><p class="lede">{lede}</p></div></header><main class="wrap">{body}</main>
<footer><div class="wrap">Thesis prototype. Built from <code>model_v4.py</code> and <code>evaluate_v4.py</code>. Generated by <code>gen_docs.py</code>.</div></footer></body></html>"""

explained = page("The Model in Plain Words", "The Model · explained simply", "How the Model tells when a trip looks unusual",
 "A phone saves where a commuter's vehicle is, once every 10 seconds. From that alone, the Model learns what a normal trip looks like, notices when a trip stops looking normal, and says how likely it is to look worse in the next minute.",
 f"""
<section><h2>The one-minute version</h2>
<p>Think of a friend who has ridden the same route many times. They know where the vehicle usually stops, how fast it usually goes, and how long a pause usually lasts. If it stopped somewhere new for a long time, or drifted away from the road it always takes, they would notice.</p>
<p>The Model does the same, using only three things from a phone: the <b>time</b>, the <b>latitude</b>, and the <b>longitude</b>. It does not need anyone to report a problem first.</p>
<div class="callout"><b>What it is not.</b> The Model does not say that anything bad has happened. "Unusual" only means "different from earlier trips". A vehicle can stop for a good reason.</div></section>

<section><h2>What goes in</h2>
<p>One position every 10 seconds for each trip. We also need the road the route follows (one for each direction), and short notes from the person recording about anything unusual that happened on a trip.</p></section>

<section><h2>How it works, in six steps</h2>
<div class="step"><div class="num">1</div><div><h3>Clean the records</h3><p>GPS makes mistakes. A position that would mean the vehicle moved faster than 50 metres per second, or sped up or slowed down faster than 10 metres per second each second, is thrown out. The same goes for duplicates and bad rows.</p></div></div>
<div class="step"><div class="num">2</div><div><h3>Measure the trip</h3><p>From the clean records we work out speed, how long the vehicle has been stopped, how far along the route it is, and how far it is from the usual road.</p></div></div>
<div class="step"><div class="num">3</div><div><h3>Learn what is normal</h3><p>For each stretch of road, each direction, and each part of the day, the Model learns the usual speed and the usual stops, using only <b>that person's earlier trips</b>. Every commuter has their own history, and it never looks at the trip it is judging.</p></div></div>
<div class="step"><div class="num">4</div><div><h3>Score how unusual each moment is</h3><p>An Isolation Forest gives every moment a score. Moments that are easy to tell apart from the rest score higher.</p></div></div>
<div class="step"><div class="num">5</div><div><h3>Pick a concern level</h3><p>The score is combined with the distance from the usual road and with how long the vehicle has stopped unexpectedly. The result is <b>Normal, Minor, Major, or Critical</b>.</p></div></div>
<div class="step"><div class="num">6</div><div><h3>Forecast the next minute</h3><p>XGBoost learns from the earlier trips what usually comes next. It gives the chance that the worst concern level in the next 60 seconds will be at least Minor, Major, or Critical, and says how sure it is.</p></div></div></section>

<section><h2>Where do the "right answers" come from?</h2>
<p>XGBoost needs examples with answers, but nobody marks which moments were unusual. So the answers are made from the trips themselves: a moment's answer is the worst concern level in the minute after it. This shows what looked unusual, not what was dangerous.</p></section>

<section><h2>Old trips expire</h2>
<p>Roads, routes and traffic change. A trip from many weeks ago may no longer show what is normal. So the Model can keep only recent trips. How recent is decided by testing several lengths and keeping the one with the fewest false alarms without losing accuracy. Expiry settings are compared using the same no-expiry reference labels.</p></section>

<section><h2>Does it work with few trips?</h2>
<p>At the start there are only a few earlier trips, so the Model knows little. We check this by judging each trip in date order and grouping the results by how many trips came before it.</p>
{NOTE}{CV}<p class="small">AP (average precision) is higher when real concerns are ranked above ordinary moments. Calibration error is lower when the stated chances match what happens. Prediction-set coverage is measured empirically on replayed trips.</p></section>

<section><h2>Too many false alarms?</h2>
<p>A tool that cries wolf teaches people to ignore it. So we count how many alert episodes it raises on ordinary trips, and we compare against a simple rule: "the current level continues".</p>
<h3 style="margin-top:14px">History length compared</h3>{SW}</section>

<section><h2>What it can and cannot tell you</h2>
<div class="two"><div class="yes"><h3>Can</h3><ul><li>Show that a trip differs from earlier trips on the same road.</li><li>Notice unexpected stops and leaving the usual route.</li><li>Give a chance and a level of confidence for the next minute.</li></ul></div>
<div class="no"><h3>Cannot</h3><ul><li>Tell whether harassment or a crime happened.</li><li>See anything that leaves no trace in the movement.</li><li>Replace a commuter asking for help.</li></ul></div></div></section>

<section><h2>Words you may hear</h2><dl>
<dt>GPS fix</dt><dd>One saved position with its time.</dd>
<dt>Isolation Forest</dt><dd>A method that finds unusual points by how easily they can be separated from the rest.</dd>
<dt>XGBoost</dt><dd>A method that learns from examples to forecast an answer from a table of measures.</dd>
<dt>Calibration</dt><dd>Making a stated chance match how often it comes true.</dd>
<dt>Prediction set</dt><dd>A short list of plausible levels. The report measures how often it contains the model-defined label.</dd>
<dt>Cold start</dt><dd>The weak early period when there are few earlier trips.</dd></dl></section>""")

TECH_PARAMS = [
 ("Recording interval", "10 s", "Short enough for stops of 30–40 s (Sabir et al., 2025; Deng et al., 2024); uses less battery than 1 Hz polling (Edwards & Hosein, 2025); also used by Bagheri et al. (2020) and Mears et al. (2021)", "Sourced"),
 ("Speed limit for cleaning", "50 m/s", "Verma et al. (2024)", "Sourced"),
 ("Acceleration limit", "±10 m/s²", "Verma et al. (2024)", "Sourced"),
 ("Error radius limit", "50 m (only if the file has an accuracy column)", "Verma et al. (2024)", "Sourced"),
 ("Route distance bands", "150 / 500 / 1,000 m", "Edwards & Hosein (2025)", "Sourced"),
 ("Stopped speed", "< 5 km/h", "Sabir et al. (2025) low-speed limit", "Sourced"),
 ("Forest and stop-length cut-offs", "robust z of 2.5 / 3 / 3.5", "Leys et al. (2013): 2.5; Iglewicz & Hoaglin: 3.5 (NIST/SEMATECH, n.d.); middle level halfway", "Sourced; middle level is the midpoint"),
 ("Isolation Forest size", "100 trees, 256-point samples", "Liu et al. (2008)", "Sourced"),
 ("Forecast window", "starts at 60 s; 30 s and 120 s compared", "Edwards & Hosein (2025): a 30 s response time means a shorter window leaves no time. No source gives the best length", "Experiment"),
 ("Road stretch / shrinkage", "100 m / K = 8", "Study's own choice; 50 and 200 m, 4 and 16 are tested", "Experiment"),
 ("Parts of the day", "four; night and day only, and no split, are compared", "Night kept apart (UN Women, 2021); rest own choice", "Experiment"),
 ("Earlier trips before the route distance uses them", "5; 3 and 10, and the larger-of-both rule, are compared", "Own choice (Edwards & Hosein, 2025 use earlier runs)", "Experiment"),
 ("History length (expiry)", "chosen by experiment (none, 14, 7 days tried)", "Gama et al. (2013, 2014): forgetting old data helps when data change", "Tuned by experiment"),
 ("Calibration trips", "latest 20% of history, at least 2", "Platt scaling after Niculescu-Mizil & Caruana (2005); 20% as a typical held-out share (Hyndman & Athanasopoulos, 2021)", "Sourced as a guide"),
]
tech = page("The Model: Technical Notes", "The Model · technical notes", "Pipeline, parameters, and evaluation",
 "What the code in model_v4.py and evaluate_v4.py does, which numbers come from the literature and which are the study's own choices, and what the latest test run shows.",
 f"""
<section><h2>Pipeline</h2>
<ol>
<li><b>Clean.</b> Drop bad rows and duplicates; drop a fix when it implies speed above 50 m/s or acceleration beyond ±10 m/s²; drop fixes with error radius above 50 m when an accuracy column exists. A trip that loses over 20% of its records is set aside. Removed on the latest run: {clean['removed']} of {clean['raw_rows']} records.</li>
<li><b>Measure.</b> Speed over about 3 s, acceleration, jerk, turning, dwell time, route progress, distance from the route line, heading difference, rolling windows measured in elapsed seconds. GPS gaps break continuity and dwell.</li>
<li><b>Context baseline.</b> Median and spread of speed per 100 m stretch × direction × hour block, shrunk toward the stretch value (K = 8); typical dwell per stretch; a spatial index of earlier trips for distance from history. Fitted only on the history passed in, which is one commuter's earlier trips.</li>
<li><b>Isolation Forest.</b> Two forests, each fitted on half the history trips. Each history trip is scored by the forest that did not see it; a new trip gets the average of both. Scores are smoothed over 30 s.</li>
<li><b>Concern level.</b> Maximum of three levels: forest score as a robust z-score against the history, route-distance band (from the planned route and, once enough history exists, variants supported by at least two earlier trips), and current stop length as a robust z-score against locally comparable completed stops (cut at 2.5, 3, 3.5).</li>
<li><b>Labels.</b> The target is the worst concern level in the next 60 seconds when the full window has GPS coverage.</li>
<li><b>XGBoost.</b> Three cumulative binary models for level ≥ 1, ≥ 2, ≥ 3 (Frank &amp; Hall, 2001). Recent trips are held out from fitting. Earlier held-out trips support Platt calibration and the last trip is used to estimate empirical prediction sets.</li>
<li><b>Replay.</b> Trips are judged one at a time in date order, each by a model fitted on earlier trips only, optionally limited to those within an expiry window.</li></ol></section>

<section><h2>Parameters and where they come from</h2>{tbl(["Parameter", "Value", "Basis", "Status"], [[html.escape(a), html.escape(b), html.escape(c), html.escape(d)] for a, b, c, d in TECH_PARAMS])}
<p class="small">Anything marked "Own choice" is not supported by a source and should be described as a design choice in the manuscript, then checked in the evaluation.</p></section>

<section><h2>Latest run</h2>{NOTE}
<h3 style="margin-top:14px">History length (expiry), same {R['common_trips']} trips in every row</h3>{SW}
<h3 style="margin-top:14px">As the history grows (no expiry)</h3>{CV}
<p>Forecast AP and baseline AP are average precision for "worst level in the next minute is Major or Critical". The baseline assumes the current level continues. Alerts are raised when the forecast chance of Major or worse is at least {R['alert']['prob']}; alerts less than {R['alert']['merge_s']:g} s apart count as one episode.</p>
<p>Unusual-event check: {html.escape(str(R['noted_events'].get('status', 'run with --labels to fill this in')))}</p></section>

<section><h2>Known limits</h2><ul>
<li>Generated trajectories exercise the pipeline. Independently reviewed field trips are needed to estimate alert performance.</li>
<li>Concern levels describe movement and are defined by the study rules.</li>
<li>Overlapping forecast windows are dependent. Prediction-set coverage is empirical.</li></ul></section>
<section><h2>Reproduce</h2><p><code>python3 evaluate_v4.py &lt;dataset_dir&gt; --labels trip_notes.csv --expiry none,14,7</code> then <code>python3 gen_docs.py</code>.</p></section>""")
open(os.path.join(ROOT, "presentation", "model-explained.html"), "w").write(explained)
open(os.path.join(ROOT, "presentation", "model-technical.html"), "w").write(tech)
print("written")
